import { Editor, Location, Point, Range } from '../../index'
import { MoveUnit, SelectionEdge } from '../../types/types'

export interface SelectionCollapseOptions {
  edge?: SelectionEdge
}

export interface SelectionMoveOptions {
  distance?: number
  unit?: MoveUnit
  reverse?: boolean
  edge?: SelectionEdge
}

export interface SelectionSetPointOptions {
  edge?: SelectionEdge
}

export interface SelectionTransforms {
  /**
   * Collapse the selection.
   */
  collapse: (editor: Editor, options?: SelectionCollapseOptions) => void

  /**
   * Unset the selection.
   */
  deselect: (editor: Editor) => void

  /**
   * Move the selection's point forward or backward.
   */
  move: (editor: Editor, options?: SelectionMoveOptions) => void

  /**
   * Set the selection to a new value.
   */
  select: (editor: Editor, target: Location) => void

  /**
   * Set new properties on one of the selection's points.
   */
  setPoint: (
    editor: Editor,
    props: Partial<Point>,
    options?: SelectionSetPointOptions
  ) => void

  /**
   * Set new properties on the selection.
   */
  setSelection: (editor: Editor, props: Partial<Range>) => void
}

// eslint-disable-next-line no-redeclare
export const SelectionTransforms: SelectionTransforms = {
  collapse(editor, options) {
    editor.collapse(options)
  },
  deselect(editor) {
    editor.deselect()
  },
  move(editor, options) {
    editor.move(options)
  },
  select(editor, target) {
    editor.select(target)
  },
  setPoint(editor, props, options) {
    editor.setPoint(props, options)
  },
  setSelection(editor, props) {
    editor.setSelection(props)
  },
}

import { Editor, EditorPositionsOptions } from '../interfaces/editor'
import { Node } from '../interfaces/node'
import { Point } from '../interfaces/point'
import { Range } from '../interfaces/range'
import { Path } from '../interfaces/path'
import {
  getCharacterDistance,
  getWordDistance,
  splitByCharacterDistance,
} from '../utils/string'

export function* positions(
  editor: Editor,
  options: EditorPositionsOptions = {}
): Generator<Point, void, undefined> {
  const {
    at = editor.selection,
    unit = 'offset',
    reverse = false,
    voids = false,
  } = options

  if (!at) {
    return
  }

  /**
   * Algorithm notes:
   *
   * Each step `distance` is dynamic depending on the underlying text
   * and the `unit` specified.  Each step, e.g., a line or word, may
   * span multiple text nodes, so we iterate through the text both on
   * two levels in step-sync:
   *
   * `leafText` stores the text on a text leaf level, and is advanced
   * through using the counters `leafTextOffset` and `leafTextRemaining`.
   *
   * `blockText` stores the text on a block level, and is shortened
   * by `distance` every time it is advanced.
   *
   * We only maintain a window of one blockText and one leafText because
   * a block node always appears before all of its leaf nodes.
   */

  const range = Editor.range(editor, at)
  const [start, end] = Range.edges(range)
  const first = reverse ? end : start
  let isNewBlock = false
  let blockText = ''
  let distance = 0 // Distance for leafText to catch up to blockText.
  let leafTextRemaining = 0
  let leafTextOffset = 0
  const skippedPaths: Path[] = []

  // Iterate through all nodes in range, grabbing entire textual content
  // of block nodes in blockText, and text nodes in leafText.
  // Exploits the fact that nodes are sequenced in such a way that we first
  // encounter the block node, then all of its text nodes, so when iterating
  // through the blockText and leafText we just need to remember a window of
  // one block node and leaf node, respectively.
  for (const [node, path] of Editor.nodes(editor, {
    at,
    reverse,
    voids,
  })) {
    // If the node is inside a skipped ancestor, do not return any points, but
    // still process its content so that the iteration state remains correct.
    const hasSkippedAncestor = skippedPaths.some(p => Path.isAncestor(p, path))

    function* maybeYield(point: Point) {
      if (!hasSkippedAncestor) {
        yield point
      }
    }

    /*
     * ELEMENT NODE - Yield position(s) for voids, collect blockText for blocks
     */
    if (Node.isElement(node)) {
      if (!editor.isSelectable(node)) {
        /**
         * If the node is not selectable, skip it and its descendants
         */
        skippedPaths.push(path)
        if (reverse) {
          if (Path.hasPrevious(path)) {
            yield* maybeYield(Editor.end(editor, Path.previous(path)))
          }
          continue
        } else {
          const nextPath = Path.next(path)
          if (Editor.hasPath(editor, nextPath)) {
            yield* maybeYield(Editor.start(editor, nextPath))
          }
          continue
        }
      }

      // Void nodes are a special case, so by default we will always
      // yield their first point. If the `voids` option is set to true,
      // then we will iterate over their content.
      if (!voids && (editor.isVoid(node) || editor.isElementReadOnly(node))) {
        yield* maybeYield(Editor.start(editor, path))
        continue
      }

      // Inline element nodes are ignored as they don't themselves
      // contribute to `blockText` or `leafText` - their parent and
      // children do.
      if (editor.isInline(node)) continue

      // Block element node - set `blockText` to its text content.
      if (Editor.hasInlines(editor, node)) {
        // We always exhaust block nodes before encountering a new one:
        //   console.assert(blockText === '',
        //     `blockText='${blockText}' - `+
        //     `not exhausted before new block node`, path)

        // Ensure range considered is capped to `range`, in the
        // start/end edge cases where block extends beyond range.
        // Equivalent to this, but presumably more performant:
        //   blockRange = Editor.range(editor, ...Editor.edges(editor, path))
        //   blockRange = Range.intersection(range, blockRange) // intersect
        //   blockText = Editor.string(editor, blockRange, { voids })
        const e = Path.isAncestor(path, end.path)
          ? end
          : Editor.end(editor, path)
        const s = Path.isAncestor(path, start.path)
          ? start
          : Editor.start(editor, path)

        blockText = Editor.string(editor, { anchor: s, focus: e }, { voids })
        isNewBlock = true
      }
    }

    /*
     * TEXT LEAF NODE - Iterate through text content, yielding
     * positions every `distance` offset according to `unit`.
     */
    if (Node.isText(node)) {
      const isFirst = Path.equals(path, first.path)

      // Proof that we always exhaust text nodes before encountering a new one:
      //   console.assert(leafTextRemaining <= 0,
      //     `leafTextRemaining=${leafTextRemaining} - `+
      //     `not exhausted before new leaf text node`, path)

      // Reset `leafText` counters for new text node.
      if (isFirst) {
        leafTextRemaining = reverse
          ? first.offset
          : node.text.length - first.offset
        leafTextOffset = first.offset // Works for reverse too.
      } else {
        leafTextRemaining = node.text.length
        leafTextOffset = reverse ? leafTextRemaining : 0
      }

      // Yield position at the start of node (potentially).
      if (isFirst || isNewBlock || unit === 'offset') {
        yield* maybeYield({ path, offset: leafTextOffset })
        isNewBlock = false
      }

      // Yield positions every (dynamically calculated) `distance` offset.
      while (true) {
        // If `leafText` has caught up with `blockText` (distance=0),
        // and if blockText is exhausted, break to get another block node,
        // otherwise advance blockText forward by the new `distance`.
        if (distance === 0) {
          if (blockText === '') break
          distance = calcDistance(blockText, unit, reverse)
          // Split the string at the previously found distance and use the
          // remaining string for the next iteration.
          blockText = splitByCharacterDistance(blockText, distance, reverse)[1]
        }

        // Advance `leafText` by the current `distance`.
        leafTextOffset = reverse
          ? leafTextOffset - distance
          : leafTextOffset + distance
        leafTextRemaining = leafTextRemaining - distance

        // If `leafText` is exhausted, break to get a new leaf node
        // and set distance to the overflow amount, so we'll (maybe)
        // catch up to blockText in the next leaf text node.
        if (leafTextRemaining < 0) {
          distance = -leafTextRemaining
          break
        }

        // Successfully walked `distance` offsets through `leafText`
        // to catch up with `blockText`, so we can reset `distance`
        // and yield this position in this node.
        distance = 0
        yield* maybeYield({ path, offset: leafTextOffset })
      }
    }
  }
  // Proof that upon completion, we've exahusted both leaf and block text:
  //   console.assert(leafTextRemaining <= 0, "leafText wasn't exhausted")
  //   console.assert(blockText === '', "blockText wasn't exhausted")

  // Helper:
  // Return the distance in offsets for a step of size `unit` on given string.
  function calcDistance(text: string, unit: string, reverse?: boolean) {
    if (unit === 'character') {
      return getCharacterDistance(text, reverse)
    } else if (unit === 'word') {
      return getWordDistance(text, reverse)
    } else if (unit === 'line' || unit === 'block') {
      return text.length
    }
    return 1
  }
}

'use client'

import { Icon } from '@iconify/react'
import { memo, useLayoutEffect, useMemo, useRef, useState } from 'react'
import useEditor, { type FloorplanSelectionTool } from '../../store/use-editor'
import { useFloorplanDraftPreview } from '../../store/use-floorplan-draft-preview'
import { furnishTools } from '../ui/action-menu/furnish-tools'
import { tools as structureTools } from '../ui/action-menu/structure-tools'
import {
  type FloorplanCursorPoint,
  projectFloorplanCursorPoint,
  resolveFloorplanCursorIndicatorPosition,
} from './floorplan-cursor-indicator-position'

type FloorplanCursorIndicator =
  | {
      kind: 'asset'
      iconSrc: string
    }
  | {
      kind: 'icon'
      icon: string
    }

type FloorplanCursorIndicatorOverlayProps = {
  cursorPosition: FloorplanCursorPoint | null
  floorplanSelectionTool: FloorplanSelectionTool
  movingOpeningType: 'door' | 'window' | null
  isPanning: boolean
  cursorColor: string
  indicatorLineHeight?: number
  indicatorBadgeOffsetX?: number
  indicatorBadgeOffsetY?: number
}

export const FloorplanCursorIndicatorOverlay = memo(function FloorplanCursorIndicatorOverlay({
  cursorPosition,
  floorplanSelectionTool,
  movingOpeningType,
  isPanning,
  cursorColor,
  indicatorLineHeight = 18,
  indicatorBadgeOffsetX = 14,
  indicatorBadgeOffsetY = 14,
}: FloorplanCursorIndicatorOverlayProps) {
  const mode = useEditor((state) => state.mode)
  const tool = useEditor((state) => state.tool)
  const structureLayer = useEditor((state) => state.structureLayer)
  const catalogCategory = useEditor((state) => state.catalogCategory)
  const cursorPoint = useFloorplanDraftPreview((state) => state.cursorPoint)
  const anchorRef = useRef<HTMLDivElement>(null)
  const [projectedCursorPosition, setProjectedCursorPosition] =
    useState<FloorplanCursorPoint | null>(null)

  const activeFloorplanToolConfig = useMemo(() => {
    if (movingOpeningType) {
      return structureTools.find((entry) => entry.id === movingOpeningType) ?? null
    }

    if (mode !== 'build' || !tool) {
      return null
    }

    if (tool === 'item' && catalogCategory) {
      return furnishTools.find((entry) => entry.catalogCategory === catalogCategory) ?? null
    }

    return structureTools.find((entry) => entry.id === tool) ?? null
  }, [catalogCategory, mode, movingOpeningType, tool])

  const indicator = useMemo<FloorplanCursorIndicator | null>(() => {
    if (activeFloorplanToolConfig) {
      return { kind: 'asset', iconSrc: activeFloorplanToolConfig.iconSrc }
    }

    if (mode === 'select' && floorplanSelectionTool === 'marquee' && structureLayer !== 'zones') {
      return { kind: 'icon', icon: 'mdi:select-drag' }
    }

    if (mode === 'delete') {
      return { kind: 'icon', icon: 'mdi:trash-can-outline' }
    }

    if (mode === 'material-paint') {
      return { kind: 'asset', iconSrc: '/icons/paint.webp' }
    }

    return null
  }, [activeFloorplanToolConfig, floorplanSelectionTool, mode, structureLayer])

  useLayoutEffect(() => {
    const anchor = anchorRef.current
    const overlayHost = anchor?.parentElement
    const scene = overlayHost?.querySelector<SVGGElement>('[data-floorplan-scene]')
    const sceneToViewport = scene?.getScreenCTM()

    if (!(cursorPoint && cursorPosition && overlayHost && sceneToViewport)) {
      setProjectedCursorPosition(null)
      return
    }

    const overlayRect = overlayHost.getBoundingClientRect()
    const nextPosition = projectFloorplanCursorPoint(cursorPoint, sceneToViewport, {
      x: overlayRect.left,
      y: overlayRect.top,
    })
    setProjectedCursorPosition((currentPosition) =>
      currentPosition &&
      currentPosition.x === nextPosition.x &&
      currentPosition.y === nextPosition.y
        ? currentPosition
        : nextPosition,
    )
  }, [cursorPoint, cursorPosition])

  const position = resolveFloorplanCursorIndicatorPosition(cursorPosition, projectedCursorPosition)

  if (!(indicator && position) || isPanning) {
    return null
  }

  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute z-20"
      ref={anchorRef}
      style={{ left: position.x, top: position.y }}
    >
      {mode === 'delete' ? (
        <div
          className="flex h-8 w-8 items-center justify-center rounded-xl border border-white/5 bg-zinc-900/95 shadow-[0_8px_16px_-4px_rgba(0,0,0,0.3),0_4px_8px_-4px_rgba(0,0,0,0.2)]"
          style={{
            boxShadow: `0 8px 16px -4px rgba(0,0,0,0.3), 0 4px 8px -4px rgba(0,0,0,0.2), 0 0 18px ${cursorColor}22`,
            transform: `translate(${indicatorBadgeOffsetX}px, ${indicatorBadgeOffsetY}px)`,
          }}
        >
          {indicator.kind === 'asset' ? (
            <img
              alt=""
              aria-hidden="true"
              className="h-5 w-5 object-contain drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
              src={indicator.iconSrc}
            />
          ) : (
            <Icon
              aria-hidden="true"
              className="drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
              color={cursorColor}
              height={18}
              icon={indicator.icon}
              width={18}
            />
          )}
        </div>
      ) : (
        <>
          <div
            className="absolute top-0 left-1/2 w-px -translate-x-1/2 -translate-y-full"
            style={{
              backgroundColor: cursorColor,
              boxShadow: `0 0 12px ${cursorColor}55`,
              height: indicatorLineHeight,
            }}
          />
          <div
            className="absolute top-0 left-1/2 flex h-8 w-8 items-center justify-center rounded-xl border border-white/5 bg-zinc-900/95 shadow-[0_8px_16px_-4px_rgba(0,0,0,0.3),0_4px_8px_-4px_rgba(0,0,0,0.2)]"
            style={{
              transform: `translate(-50%, calc(-100% - ${indicatorLineHeight}px))`,
            }}
          >
            {indicator.kind === 'asset' ? (
              <img
                alt=""
                aria-hidden="true"
                className="h-5 w-5 object-contain drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
                src={indicator.iconSrc}
              />
            ) : (
              <Icon
                aria-hidden="true"
                className="drop-shadow-[0_2px_4px_rgba(0,0,0,0.5)]"
                color="white"
                height={18}
                icon={indicator.icon}
                width={18}
              />
            )}
          </div>
        </>
      )}
    </div>
  )
})

'use client'

import type { ZoneNode as ZoneNodeType } from '@pascal-app/core'
import type { WallPlanPoint } from '../tools/wall/wall-drafting'

type ModifierKeys = {
  meta: boolean
  ctrl: boolean
  shift: boolean
  /** Alt alone: select one session-group member without expanding. */
  alt: boolean
}

type ResolveFloorplanBackgroundSelectionArgs = {
  canSelectElementFloorplanGeometry: boolean
  canSelectFloorplanZones: boolean
  currentSelectedIds: string[]
  /** Session-group expand on plain click (not on modifier/Alt). */
  expandIdsForNode?: (nodeId: string) => string[] | null
  getFloorplanHitIdAtPoint: (planPoint: WallPlanPoint) => string | null
  isWallBuildActive: boolean
  modifierKeys: ModifierKeys
  planPoint: WallPlanPoint
  structureLayer: string
}

function hasToggleModifier(modifierKeys: ModifierKeys): boolean {
  return modifierKeys.meta || modifierKeys.ctrl || modifierKeys.shift
}

function resolveHitSelection(
  hitId: string,
  currentSelectedIds: string[],
  modifierKeys: ModifierKeys,
  expandIdsForNode?: (nodeId: string) => string[] | null,
): string[] {
  if (hasToggleModifier(modifierKeys)) {
    return currentSelectedIds.includes(hitId)
      ? currentSelectedIds.filter((selectedId) => selectedId !== hitId)
      : [...currentSelectedIds, hitId]
  }
  if (modifierKeys.alt) return [hitId]
  const expanded = expandIdsForNode?.(hitId)
  return expanded && expanded.length > 1 ? expanded : [hitId]
}

export type FloorplanBackgroundSelectionResult =
  | {
      handled: true
      kind: 'select-zone'
      zoneId: ZoneNodeType['id']
    }
  | {
      handled: true
      kind: 'select-elements'
      selectedIds: string[]
    }
  | {
      handled: true
      kind: 'clear-zones'
    }
  | {
      handled: true
      kind: 'clear-elements'
      preserveSelection: boolean
    }
  | {
      handled: false
    }

export function resolveFloorplanBackgroundSelection({
  canSelectElementFloorplanGeometry,
  canSelectFloorplanZones,
  currentSelectedIds,
  expandIdsForNode,
  getFloorplanHitIdAtPoint,
  isWallBuildActive,
  modifierKeys,
  planPoint,
  structureLayer,
}: ResolveFloorplanBackgroundSelectionArgs): FloorplanBackgroundSelectionResult {
  if (canSelectFloorplanZones) {
    const zoneId = getFloorplanHitIdAtPoint(planPoint)
    if (zoneId) {
      return {
        handled: true,
        kind: 'select-zone',
        zoneId: zoneId as ZoneNodeType['id'],
      }
    }
  }

  if (canSelectElementFloorplanGeometry) {
    const hitId = getFloorplanHitIdAtPoint(planPoint)
    if (hitId) {
      return {
        handled: true,
        kind: 'select-elements',
        selectedIds: resolveHitSelection(hitId, currentSelectedIds, modifierKeys, expandIdsForNode),
      }
    }
  }

  if (!isWallBuildActive) {
    if (structureLayer === 'zones') {
      return {
        handled: true,
        kind: 'clear-zones',
      }
    }

    return {
      handled: true,
      kind: 'clear-elements',
      preserveSelection: hasToggleModifier(modifierKeys),
    }
  }

  return { handled: false }
}

