import type { IPosition, ITextRange, Nullable } from '@univerjs/core';
import type {
    DocumentSkeleton,
    IDocsTableRenderViewport,
    IDocumentOffsetConfig,
    IDocumentSkeletonColumn,
    IDocumentSkeletonDivide,
    IDocumentSkeletonGlyph,
    IDocumentSkeletonLine,
    IDocumentSkeletonPage,
    IDocumentSkeletonRow,
    IDocumentSkeletonSection,
    IDocumentSkeletonTable,
    INodePosition,
    IPoint,
} from '@univerjs/engine-render';
import { DataStreamTreeTokenType, PositionedObjectLayoutType } from '@univerjs/core';
import { shouldUseInlineTextSelectionForDocsCustomBlockDrawing } from '@univerjs/docs';
import {
    compareDocumentSkeletonNestedPagePathOrder,
    DocumentSkeletonPageType,
    getDocsTableRenderViewport,
    getDocumentSkeletonNestedPageOffset,
    getPageFromPath,
    getTableIdAndSliceIndex,
    GlyphType,
    Liquid,
} from '@univerjs/engine-render';

export function findDocRangeNodePositions(
    skeleton: DocumentSkeleton,
    startIndex: number,
    endIndex: number,
    segmentId = '',
    pageIndex = -1
): { startPosition: INodePosition; endPosition: INodePosition } | undefined {
    const dataStream = skeleton.getViewModel?.().getDataModel?.().getSelfOrHeaderFooterModel?.(segmentId)?.getBody?.()?.dataStream as string | undefined;
    let startPosition: Nullable<INodePosition>;
    for (let index = startIndex; index <= endIndex && !startPosition; index++) {
        if (dataStream && isStructuralControl(dataStream.charCodeAt(index))) continue;
        startPosition = skeleton.findNodePositionByCharIndex(index, true, segmentId, pageIndex);
    }

    let endPosition: Nullable<INodePosition>;
    for (let index = endIndex; index >= startIndex && !endPosition; index--) {
        if (dataStream && isStructuralControl(dataStream.charCodeAt(index))) continue;
        endPosition = skeleton.findNodePositionByCharIndex(index, false, segmentId, pageIndex);
    }

    if (!startPosition || !endPosition) return;

    // NodePositionConvertToCursor traverses a cell selection through one nested
    // page path. A row/table wrapper can start and end in different cells, so
    // feeding both positions to it indexes the first cell with the second cell's
    // line coordinates. Structural table SDTs are not text hit targets; their
    // inner controls are, and are resolved independently.
    if (startPosition.pageType !== endPosition.pageType) return;
    if (
        startPosition.pageType === DocumentSkeletonPageType.CELL &&
        endPosition.pageType === DocumentSkeletonPageType.CELL &&
        !sameNodePath(startPosition.path, endPosition.path)
    ) {
        return;
    }

    return { startPosition, endPosition };
}

function isStructuralControl(code: number): boolean {
    return code < 0x20 && code !== 0x09;
}

function sameNodePath(left: Array<string | number>, right: Array<string | number>): boolean {
    return left.length === right.length && left.every((part, index) => part === right[index]);
}

export enum NodePositionStateType {
    NORMAL,
    START,
    END,
}

export enum NodePositionType {
    page,
    section,
    column,
    line,
    divide,
    glyph,
}

export interface ICurrentNodePositionState {
    page: NodePositionStateType;
    section: NodePositionStateType;
    column: NodePositionStateType;
    line: NodePositionStateType;
    divide: NodePositionStateType;
    glyph: NodePositionStateType;
}

export const NodePositionMap = {
    page: 0,
    section: 1,
    column: 2,
    line: 3,
    divide: 4,
    glyph: 5,
};

export function compareNodePositionLogic(pos1: INodePosition, pos2: INodePosition) {
    const nestedPagePathOrder = compareDocumentSkeletonNestedPagePathOrder(pos1, pos2);
    if (nestedPagePathOrder != null) {
        return nestedPagePathOrder;
    }

    if (pos1.page > pos2.page) {
        return false;
    }

    if (pos1.page < pos2.page) {
        return true;
    }

    if (pos1.section > pos2.section) {
        return false;
    }

    if (pos1.section < pos2.section) {
        return true;
    }

    if (pos1.column > pos2.column) {
        return false;
    }

    if (pos1.column < pos2.column) {
        return true;
    }

    if (pos1.line > pos2.line) {
        return false;
    }

    if (pos1.line < pos2.line) {
        return true;
    }

    if (pos1.divide > pos2.divide) {
        return false;
    }

    if (pos1.divide < pos2.divide) {
        return true;
    }

    if (pos1.glyph > pos2.glyph) {
        return false;
    }

    if (pos1.glyph < pos2.glyph) {
        return true;
    }

    return true;
}

export function compareNodePosition(pos1: INodePosition, pos2: INodePosition) {
    const compare = compareNodePositionLogic(pos1, pos2);

    if (compare) {
        return {
            start: pos1,
            end: pos2,
        };
    }

    return {
        start: pos2,
        end: pos1,
    };
}

export function getOneTextSelectionRange(rangeList: ITextRange[]): Nullable<ITextRange> {
    const rangeCount = rangeList.length;
    if (rangeCount === 0) {
        return;
    }

    const firstCursor = rangeList[0];

    const lastCursor = rangeList[rangeCount - 1];

    const collapsed = rangeList.length === 1 && firstCursor.collapsed;

    return {
        startOffset: firstCursor.startOffset,
        endOffset: lastCursor.endOffset,
        collapsed,
    };
}

function getOffsetInDivide(
    glyphGroup: IDocumentSkeletonGlyph[],
    startGlyphIndex: number,
    endGlyphIndex: number,
    st: number
) {
    let startOffset = st;
    let endOffset = st;

    for (let i = 0; i < glyphGroup.length; i++) {
        const glyph = glyphGroup[i];
        const contentLength = glyph.count;

        if (i < startGlyphIndex) {
            startOffset += contentLength;
        }

        if (i < endGlyphIndex) {
            endOffset += contentLength;
        }
    }

    return {
        startOffset,
        endOffset,
    };
}

export function pushToPoints(position: IPosition) {
    const { startX, startY, endX, endY } = position;
    const points: Array<{ x: number; y: number }> = [];

    points.push({
        x: startX,
        y: startY,
    });

    points.push({
        x: endX,
        y: startY,
    });

    points.push({
        x: endX,
        y: endY,
    });

    points.push({
        x: startX,
        y: endY,
    });

    points.push({
        x: startX,
        y: startY,
    });

    return points;
}

export class NodePositionConvertToCursor {
    private _liquid = new Liquid();
    private _horizontalClip: Nullable<{ left: number; right: number }> = null;
    private _verticalCellOrigin: Nullable<{ x: number; y: number; width: number }> = null;

    private _currentStartState: ICurrentNodePositionState = {
        page: NodePositionStateType.NORMAL,
        section: NodePositionStateType.NORMAL,
        column: NodePositionStateType.NORMAL,
        line: NodePositionStateType.NORMAL,
        divide: NodePositionStateType.NORMAL,
        glyph: NodePositionStateType.NORMAL,
    };

    private _currentEndState: ICurrentNodePositionState = {
        page: NodePositionStateType.NORMAL,
        section: NodePositionStateType.NORMAL,
        column: NodePositionStateType.NORMAL,
